class InMemoryUserRepo final : public UserRepository {
 public:
  std::optional<User> find(const UserId& id) override {
    auto it = users_.find(id);
    return it == users_.end() ? std::nullopt : std::optional<User>(it->second);
  }
  void save(const User& u) override { users_.insert_or_assign(u.id, u); }

 private:
  std::unordered_map<UserId, User> users_;
};
